import json

def note(name_oct):
    """Convert note name like 'C-4' or 'C#4' to FT2 note number (0-95)"""
    # Handle both C-4 and C#4 formats
    if '#' in name_oct:
        # C#4 format
        name = name_oct[:2]
        octave = int(name_oct[2:])
    else:
        # C-4 format
        name = name_oct[0]
        octave = int(name_oct[2:])
    note_map = {'C':0, 'C#':1, 'D':2, 'D#':3, 'E':4, 'F':5, 'F#':6, 'G':7, 'G#':8, 'A':9, 'A#':10, 'B':11}
    return note_map[name] + octave * 12

